/// <summary>
/// AVA/WEN/20250109    AVA_012791_CredManBlockExclusionRules
/// da das Kredit und Inkasso Modul so gegen Erweiterungen abgeschottet ist, wird vor der Sperrregelprüfung die Kreditverwaltungsgruppe auf die Debitorenkreditgruppe umgestellt
/// nach der Sperrregelprüfung wird wieder die Kreditverwaltungsgruppe auf den ursprünglichen Wert gesetzt
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <param name = "_creditMaxCheck">CustCreditMaxCheck</param>
public static void salesFormRelease(SalesTable _salesTable, CustCreditMaxCheck _creditMaxCheck)
{
    CustTable   ct;
    CredManCreditLimitId    crlCustGroup;

    ct = _salesTable.custTable_InvoiceAccount(true);
    crlCustGroup = ct.AVACreditLimitCustGroup();

    if (crlCustGroup)
    {
        ttsbegin;
        ct.AVACredManGroupId = ct.CredManGroupId;
        ct.CredManGroupId = ct.AVACreditLimitCustGroup();
        ct.doUpdate();
        ttscommit;
    }

    next salesFormRelease(_salesTable, _creditMaxCheck);

    if (crlCustGroup)
    {
        ttsbegin;
        ct.CredManGroupId = ct.AVACredManGroupId;
        ct.doUpdate();
        ttscommit;
    }
}
